#!/bin/bash
# clipsmith render worker — runs INSIDE the clipsmith-render WSL distro
# (Ubuntu 22.04, Mesa 23.2 D3D12 GL). Invoked by clipsmith.render as:
#
#     wsl -d clipsmith-render -e bash <this file> <job.env>
#
# job.env is a KEY='value' file generated by clipsmith.render
# (build_job_env has the full variable list).
#
# Encodes the verified render gotchas so they
# never have to be rediscovered:
#   * classic renderer only (+set vid_renderer 0) — the D3D12 GL cap is 4.2,
#     the modern renderer needs GLSL 4.30 and falls back to untextured B/W
#   * cfg pair: re_trigger on "matchdate:" -> alias exec's the capgo cfg
#     (track/demo_jump/demo_capture are cbuf_safe-blacklisted in trigger
#     context, cmd.c:1762; exec inserts into cbuf_main)
#   * autotrack cleared BEFORE demo_jump, track <uid> AFTER the seek lands
#     (Cam_Lock clears its own lock flag, cl_cam.c:202)
#   * console suppressed (toggleconsole + con_notify 0) in the exec'd cfg
#   * basedir staged on distro ext4 (~8.4 fps vs 2-4 on /mnt/c) as a
#     hardlink clone of the content basedir (the nQuake texture pk3s are
#     required — a minimal basedir renders GREY)
#   * early validation: capture frame #EARLY_FRAME is checked (signalstats)
#     — black/dead captures abort cheaply; low saturation warns and exports
#     the frame for the operator's visual spot-check
#
# Never touches the Windows GPU/display stack. Kills ONLY its own process
# group and its own Xvfb display — a parallel render may be live on another
# DISPLAY in this same distro.
set -uo pipefail

ENV_FILE="${1:?usage: render_worker.sh <job.env>}"
# shellcheck disable=SC1090
source "$ENV_FILE"

# Required variables (fail fast on any hole in the contract).
: "${JOB_ID:?}" "${DISPLAY_NUM:?}" "${WIDTH:?}" "${HEIGHT:?}" "${FPS:?}"
: "${CAPTURE_S:?}" "${EXPECTED_FRAMES:?}" "${EARLY_FRAME:?}"
: "${DEMO_SRC:?}" "${DEMO_NAME:?}" "${CFG_DIR:?}" "${MAP_NAME:?}"
: "${BASE_CONTENT:?}" "${ENGINE_DIR:?}" "${STAGING_ROOT:?}" "${HARD_TIMEOUT:?}"
: "${OUT_DIR:?}" "${OUT_NAME:?}" "${KEEP_STAGING:?}"
MAP_SRC="${MAP_SRC:-}"

JOB="$STAGING_ROOT/job-$JOB_ID"
BASEDIR="$JOB/nquake"
ENG_PID=""
XVFB_PID=""

# Early-validation thresholds. A black/dead capture has YAVG near 0 — hard
# abort below 16. Saturation is only a WARNING: calibration on real frames
# (2026-06-10, e1m2) showed a perfectly textured grey-stone map reads
# SATAVG 0.98 — indistinguishable from the untextured-GREY failure by pixel
# stats — so low saturation exports the frame for the operator's visual
# spot-check instead of aborting. The structural cause of the GREY render
# (missing texture pk3s) is prevented by cloning the full content basedir.
MIN_YAVG=16
WARN_SATAVG=8

cleanup() {  # processes only — also called mid-script before assembly
  if [ -n "$ENG_PID" ]; then
    kill -TERM -- "-$ENG_PID" 2>/dev/null
    sleep 1
    kill -KILL -- "-$ENG_PID" 2>/dev/null
  fi
  [ -n "$XVFB_PID" ] && kill "$XVFB_PID" 2>/dev/null
}
on_exit() {
  local code=$?
  cleanup
  # staging removed on EVERY exit unless explicitly kept — failure paths must
  # not accumulate hardlink clones + PNG runs in the distro. The
  # released .mov is copied OUT of $JOB before exit, so this is always safe.
  # Diagnostics survive: on failure the small logs are salvaged first.
  if [ "$code" -ne 0 ] && [ -d "$JOB" ]; then
    local sal="$STAGING_ROOT/failed-$JOB_ID-logs"
    mkdir -p "$sal"
    cp "$JOB/engine.log" "$sal/" 2>/dev/null
    cp "$BASEDIR/qw/qconsole.log" "$sal/" 2>/dev/null
    cp "$CFG_DIR/validation_frame.png" "$CFG_DIR/blackdetect.txt" "$sal/" 2>/dev/null
    echo "WORKER: failure logs salvaged to $sal" >&2
  fi
  [ "$KEEP_STAGING" = "1" ] || rm -rf "$JOB"
}
# run on any exit, including external INT/TERM — not just die()/success
trap on_exit EXIT INT TERM

die() {  # die <exit-code> <message>
  local code=$1; shift
  echo "WORKER_FAIL($code): $*" >&2
  if [ -f "$BASEDIR/qw/qconsole.log" ]; then
    echo "--- qconsole.log (clipsmith/error lines) ---" >&2
    grep -aE 'CLIPSMITH|cannot be used|Error|error|no such player|no player with|Couldn.t load' \
      "$BASEDIR/qw/qconsole.log" 2>/dev/null | head -12 >&2
  fi
  if [ -f "$JOB/engine.log" ]; then
    echo "--- engine.log tail ---" >&2
    tail -8 "$JOB/engine.log" >&2
  fi
  exit "$code"
}

# ---------------------------------------------------------------- staging
echo "WORKER: staging job-$JOB_ID under $STAGING_ROOT (ext4)"
rm -rf "$JOB"
mkdir -p "$JOB"
# Hardlink clone: zero-copy, same filesystem — but volatile files must be
# UNLINKED (not truncated) so writes create fresh inodes instead of mutating
# the shared content tree.
cp -al "$BASE_CONTENT" "$BASEDIR" || die 10 "hardlink clone of $BASE_CONTENT failed"
rm -rf "$BASEDIR/logs" "$BASEDIR/capture" "$BASEDIR/qw/capture"
rm -f "$BASEDIR/qw/qconsole.log" "$BASEDIR/qw/config.cfg" \
      "$BASEDIR"/qw/clipsmith_*.cfg "$BASEDIR"/qw/parity_*.cfg \
      "$BASEDIR"/qw/komodo*.cfg "$BASEDIR"/qw/demos/*.mvd 2>/dev/null
mkdir -p "$BASEDIR/qw/demos"

[ -f "$DEMO_SRC" ] || die 10 "demo not found: $DEMO_SRC"
DEMO_TMP="$BASEDIR/qw/demos/$DEMO_NAME.part"
rm -f "$DEMO_TMP"
gunzip -c "$DEMO_SRC" > "$DEMO_TMP" || die 10 "gunzip $DEMO_SRC failed"
mv "$DEMO_TMP" "$BASEDIR/qw/demos/$DEMO_NAME" || die 10 "atomic demo stage failed"

# cfg pair + the parity HUD layer (#20) the arm cfg exec's.
cp "$CFG_DIR/clipsmith_arm.cfg" "$CFG_DIR/clipsmith_capgo.cfg" \
   "$CFG_DIR/parity_hud.cfg" "$BASEDIR/qw/" \
  || die 10 "cfg copy from $CFG_DIR failed"

# Custom-map provisioning: id1 maps live inside pak0.pak; anything else
# (e.g. schloss) is supplied loose by the orchestrator from the Windows
# nQuake install (read-only source — outputs NEVER go there).
if [ ! -f "$BASEDIR/qw/maps/$MAP_NAME.bsp" ] && [ ! -f "$BASEDIR/id1/maps/$MAP_NAME.bsp" ]; then
  if [ -n "$MAP_SRC" ] && [ -f "$MAP_SRC" ]; then
    mkdir -p "$BASEDIR/qw/maps"
    cp "$MAP_SRC" "$BASEDIR/qw/maps/$MAP_NAME.bsp" || die 10 "map copy failed"
    echo "WORKER: provisioned maps/$MAP_NAME.bsp from $MAP_SRC"
  else
    echo "WORKER: no loose $MAP_NAME.bsp and no MAP_SRC — assuming it lives in a pak/pk3"
  fi
fi

# ------------------------------------------------------------------- Xvfb
# Own display only — a parallel render may own another :N in this distro.
pkill -f "Xvfb :$DISPLAY_NUM" 2>/dev/null
sleep 1
rm -f "/tmp/.X${DISPLAY_NUM}-lock" "/tmp/.X11-unix/X${DISPLAY_NUM}" 2>/dev/null
Xvfb ":$DISPLAY_NUM" -screen 0 "${WIDTH}x${HEIGHT}x24" &
XVFB_PID=$!
sleep 2
kill -0 "$XVFB_PID" 2>/dev/null || die 11 "Xvfb :$DISPLAY_NUM did not start"

# ----------------------------------------------------------------- engine
[ -x "$ENGINE_DIR/squashfs-root/AppRun" ] || die 11 "engine missing: $ENGINE_DIR/squashfs-root/AppRun"
echo "WORKER: launching ezQuake (classic renderer) on :$DISPLAY_NUM, capture ${CAPTURE_S}s @ ${FPS}fps (${EXPECTED_FRAMES} frames)"
cd "$ENGINE_DIR"
DISPLAY=":$DISPLAY_NUM" APPDIR="$ENGINE_DIR/squashfs-root" \
  setsid timeout "$HARD_TIMEOUT" "$ENGINE_DIR/squashfs-root/AppRun" \
    -basedir "$BASEDIR" -game qw -condebug \
    -width "$WIDTH" -height "$HEIGHT" \
    +set vid_renderer 0 \
    +exec clipsmith_arm.cfg \
    > "$JOB/engine.log" 2>&1 &
ENG_PID=$!

find_capdir() {
  ls -d "$BASEDIR"/capture/capture_* "$BASEDIR"/qw/capture/capture_* 2>/dev/null | head -1
}

# ------------------------------------------- early validation (frame ~N)
# Wait for the seek to land and frame #EARLY_FRAME to appear, then check it
# is neither black nor the grey untextured render before letting the full
# capture run out. Caught two bad renders cheaply in the multi-POV run.
CAPDIR=""
FRAME=""
PROBE_FRAME="$EARLY_FRAME"
if [ "$PROBE_FRAME" -gt $((EXPECTED_FRAMES - 2)) ]; then
  PROBE_FRAME=$((EXPECTED_FRAMES - 2))
fi
if [ "$PROBE_FRAME" -lt 1 ]; then
  PROBE_FRAME=1
fi
deadline=$((SECONDS + 420))
while [ $SECONDS -lt $deadline ]; do
  kill -0 "$ENG_PID" 2>/dev/null || die 12 "engine exited before capture started"
  [ -z "$CAPDIR" ] && CAPDIR=$(find_capdir)
  if [ -n "$CAPDIR" ]; then
    FRAME=$(ls "$CAPDIR"/*.png 2>/dev/null | sed -n "${PROBE_FRAME}p")
    [ -n "$FRAME" ] && break
  fi
  sleep 2
done
[ -n "$FRAME" ] || die 12 "no capture frame #$PROBE_FRAME within 420s"

stats=$(ffmpeg -hide_banner -nostats -i "$FRAME" \
          -vf "signalstats,metadata=print:file=-" -f null - 2>/dev/null)
yavg=$(grep -oE 'signalstats\.YAVG=[0-9.]+' <<<"$stats" | head -1 | cut -d= -f2)
satavg=$(grep -oE 'signalstats\.SATAVG=[0-9.]+' <<<"$stats" | head -1 | cut -d= -f2)
[ -n "$yavg" ] && [ -n "$satavg" ] || die 13 "signalstats parse failed on $FRAME"
cp "$FRAME" "$CFG_DIR/validation_frame.png" 2>/dev/null
echo "WORKER: early validation frame #$PROBE_FRAME YAVG=$yavg SATAVG=$satavg"
awk -v y="$yavg" -v ymin="$MIN_YAVG" 'BEGIN{exit !(y<ymin)}' \
  && die 13 "early validation FAILED: frame is black (YAVG=$yavg < $MIN_YAVG)"
if awk -v s="$satavg" -v smin="$WARN_SATAVG" 'BEGIN{exit !(s<smin)}'; then
  echo "WORKER_WARN: low saturation (SATAVG=$satavg) — could be a grey map OR" \
       "the untextured-GREY render; visually verify validation_frame.png"
fi
echo "WORKER: EARLY_VALIDATION_OK"

# -------------------------------------------------- wait for full capture
# demo_capture stops itself after CAPTURE_S and finalizes audio.wav; the
# engine keeps playing the demo, so once the frame count is reached we give
# a short grace for the wav header and kill our own process group.
last_count=0
stall=0
while :; do
  count=$(ls "$CAPDIR" 2>/dev/null | grep -c '\.png$')
  if [ "$count" -ge "$EXPECTED_FRAMES" ]; then
    echo "WORKER: capture complete ($count/$EXPECTED_FRAMES frames)"
    sleep 8
    break
  fi
  if ! kill -0 "$ENG_PID" 2>/dev/null; then
    die 14 "engine died at $count/$EXPECTED_FRAMES frames"
  fi
  if [ "$count" -eq "$last_count" ]; then
    stall=$((stall + 1))
    [ $stall -ge 36 ] && die 14 "capture stalled at $count/$EXPECTED_FRAMES frames for 180s"
  else
    stall=0
    last_count=$count
  fi
  sleep 5
done
cleanup
ENG_PID=""; XVFB_PID=""

[ -s "$CAPDIR/audio.wav" ] || die 15 "audio.wav missing or empty in $CAPDIR"

# --------------------------------------------------------------- assemble
# Locked intermediate (issue #22, docs/picture-settings.md): the raw clip is
# the Resolve ingest master, not a delivery file. H.264 CRF 14 preset slow is
# visually transparent on QW content at ~1/6 the size of DNxHR; GOP = 1 s
# (-g $FPS) keeps Resolve scrubbing responsive; audio stays PCM (the wav is
# the only lossless audio generation — don't spend it on AAC before Resolve),
# which requires the .mov container (mp4+pcm is a compatibility trap).
echo "WORKER: assembling $OUT_NAME.mov"
ffmpeg -y -loglevel error \
  -framerate "$FPS" -i "$CAPDIR/shot-%06d.png" -i "$CAPDIR/audio.wav" \
  -map 0:v -map 1:a -c:v libx264 -crf 14 -preset slow -g "$FPS" \
  -pix_fmt yuv420p -c:a pcm_s16le -r "$FPS" \
  "$JOB/$OUT_NAME.mov" || die 16 "ffmpeg assembly failed"

# ------------------------------------------------------------ blackdetect
BD=$(ffmpeg -hide_banner -nostats -i "$JOB/$OUT_NAME.mov" \
       -vf "blackdetect=d=0.5:pix_th=0.05" -an -f null - 2>&1 \
     | grep -a 'black_start' || true)
printf '%s\n' "${BD:-}" > "$CFG_DIR/blackdetect.txt"
echo "BLACKDETECT: ${BD:-none}"

mkdir -p "$OUT_DIR"
cp "$JOB/$OUT_NAME.mov" "$OUT_DIR/$OUT_NAME.mov" || die 17 "copy to $OUT_DIR failed"
SIZE=$(stat -c%s "$OUT_DIR/$OUT_NAME.mov")
echo "WORKER: staged $OUT_DIR/$OUT_NAME.mov ($SIZE bytes, $count frames)"

if [ -n "$BD" ]; then
  die 18 "blackdetect found black intervals — mov staged for inspection, not releasing"
fi

echo "WORKER_OK: $OUT_NAME.mov"
exit 0
